import inspect,casa_tool
s=casa_tool.Session('/app/instance.npz')
print('check impl:')
print(inspect.getsource(type(s.env)._check_success))
print('drawer attrs')
for k,v in vars(s.env.drawer).items():
 print(k,repr(v)[:1000])
print('drawer methods')
for n in dir(s.env.drawer):
 if any(x in n.lower() for x in ['handle','joint','pos','size']):
  v=getattr(s.env.drawer,n)
  if not callable(v): print(n,repr(v)[:500])
print('world xyz cabinet and robot base:')
for b in range(s.model.nbody):
 n=s.model.body(b).name
 if any(x in n for x in ['bottom_main','robot0_base','mobilebase0_base','drawer']):
  print(b,n,'xpos',s.data.body(b).xpos.copy(),'quat',s.data.body(b).xquat.copy())
print('geom related handles')
for i in range(s.model.ngeom):
 n=s.model.geom(i).name
 if 'bottom_main_group_1' in n:
  print(i,n,'body',s.model.body(s.model.geom_bodyid[i]).name,'type',s.model.geom_type[i], 'size',s.model.geom_size[i].copy())
