 n=s.model.body(i).name
 if n.startswith(d.name): print('body',i,n,'pos',s.data.body(i).xpos.copy(),'quat',s.data.body(i).xquat.copy())
for i in range(s.model.ngeom):
 n=s.model.geom(i).name
 if d.name in n and ('handle' in n or 'door' in n):
  print('geom',i,n,'body',s.model.body(s.model.geom_bodyid[i]).name, 'size',s.model.geom_size[i], 'pos',s.data.geom(i).xpos.copy())
print('env target qpos %',d.get_door_state(s.env), 'all target joint qpos')
print('qpos addresses',[(j,s.model.joint(j).name,s.model.jnt_qposadr[j],s.data.qpos[s.model.jnt_qposadr[j]]) for j in range(s.model.njnt) if 'stack_4' in s.model.joint(j).name])
print('eef sites')
for i in range(s.model.nsite):
 n=s.model.site(i).name
 if n in ['gripper0_right_grip_site','robot0_right_eef_site'] or 'eef' in n: print(n,s.data.site(n).xpos.copy(),s.data.site(n).xmat.copy().reshape(3,3))
print('eef body',s.data.body('gripper0_right_gripper_base').xpos.copy() if 'gripper0_right_gripper_base' in [s.model.body(i).name for i in range(s.model.nbody)] else 'none')
