import numpy as np, casa_tool
A=np.load('/app/output/trajectory.npz',allow_pickle=False)['actions']
s=casa_tool.Session('/app/instance.npz')
r=s.replay(A)
j=s.model.joint(s.env.drawer.joints[0]).qposadr[0]
print('shape',A.shape,'result',r,'drawer_qpos',float(s.data.qpos[j]),'fraction',s.env.drawer.get_door_state(s.env),flush=True)
PY";
const rs = await Promise.all([1,2].map(async i => {
  const r = await tools.exec_command({cmd, yield_time_ms:30000, max_output_tokens:1200});
  return {run:i,...r};
}));
for (const r of rs) text(JSON.stringify(r));

